import unittest
from candidate import count_distinct_characters

class TestCountDistinctCharacters(unittest.TestCase):
    def test_mixed_case(self):
        self.assertEqual(count_distinct_characters('xyzXYZ'), 3)

    def test_all_uppercase(self):
        self.assertEqual(count_distinct_characters('ABCDEF'), 6)

    def test_all_lowercase(self):
        self.assertEqual(count_distinct_characters('abcdef'), 6)

    def test_single_character(self):
        self.assertEqual(count_distinct_characters('a'), 1)

    def test_empty_string(self):
        self.assertEqual(count_distinct_characters(''), 0)

    def test_whitespace_only(self):
        self.assertEqual(count_distinct_characters('   '), 1)

    def test_numbers_and_symbols(self):
        self.assertEqual(count_distinct_characters('@#$123'), 6)

    def test_unicode_characters(self):
        self.assertEqual(count_distinct_characters('éàü'), 3)

    def test_newlines_and_tabs(self):
        self.assertEqual(count_distinct_characters('\n\t\r'), 3)

    def test_repeated_chars_only(self):
        self.assertEqual(count_distinct_characters('aaaaBBBbb!@#'), 5)

    def test_none_input_raises_exception(self):
        with self.assertRaises(Exception):
            count_distinct_characters(None)

    def test_integer_input_raises_exception(self):
        with self.assertRaises(AttributeError):
            count_distinct_characters(12345)

    def test_list_input_raises_exception(self):
        with self.assertRaises(AttributeError):
            count_distinct_characters([1, 2, 3])

if __name__ == '__main__':
    unittest.main()
